// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

interface IImageProcessor {
    function process(bytes calldata data, uint256 jobId) external returns (bool);
    function getResult(uint256 jobId) external view returns (bytes memory);
}

interface ICallback {
    function onProcessingComplete(uint256 jobId, bytes calldata result) external;
}

contract ImagePipelineRegistry is Ownable, ReentrancyGuard {
    struct ProcessorEntry {
        address implementation;
        bytes4 selector;
        bool active;
        uint256 gasLimit;
    }

    struct Job {
        address requester;
        uint256 processorIndex;
        bytes inputData;
        bytes outputData;
        JobState state;
        address callbackTarget;
        bytes4 callbackSelector;
    }

    enum JobState { Pending, Processing, Complete, Failed }

    mapping(uint256 => ProcessorEntry) public processors;
    mapping(uint256 => Job) public jobs;
    mapping(address => bool) public approvedProcessors;
    mapping(address => bool) public approvedCallbackTargets;
    uint256 public processorCount;
    uint256 public jobCount;
    uint256 public constant MAX_GAS_LIMIT = 500000;
    uint256 public constant CALLBACK_GAS_LIMIT = 100000;

    event JobCreated(uint256 indexed jobId, address indexed requester);
    event JobCompleted(uint256 indexed jobId);
    event ProcessorRegistered(uint256 indexed processorId, address implementation);

    modifier onlyApprovedProcessor(address proc) {
        require(approvedProcessors[proc], "Processor not approved");
        _;
    }

    function registerProcessor(
        address _implementation,
        bytes4 _selector,
        uint256 _gasLimit
    ) external onlyOwner {
        require(_implementation != address(0), "Invalid address");
        require(_gasLimit <= MAX_GAS_LIMIT, "Gas limit exceeded");
        require(_implementation.code.length > 0, "Not a contract");

        uint256 id = processorCount++;
        processors[id] = ProcessorEntry({
            implementation: _implementation,
            selector: _selector,
            active: true,
            gasLimit: _gasLimit
        });
        approvedProcessors[_implementation] = true;
        emit ProcessorRegistered(id, _implementation);
    }

    function approveCallbackTarget(address target) external onlyOwner {
        require(target != address(0), "Invalid address");
        require(target.code.length > 0, "Not a contract");
        approvedCallbackTargets[target] = true;
    }

    function submitJob(
        uint256 processorId,
        bytes calldata inputData,
        address callbackTarget,
        bytes4 callbackSelector
    ) external nonReentrant returns (uint256) {
        ProcessorEntry storage proc = processors[processorId];
        require(proc.active, "Processor inactive");
        require(inputData.length > 0 && inputData.length <= 65536, "Invalid input size");
        require(
            callbackTarget == address(0) || approvedCallbackTargets[callbackTarget],
            "Callback target not approved"
        );

        uint256 jobId = jobCount++;
        jobs[jobId] = Job({
            requester: msg.sender,
            processorIndex: processorId,
            inputData: inputData,
            outputData: new bytes(0),
            state: JobState.Pending,
            callbackTarget: callbackTarget,
            callbackSelector: callbackSelector
        });

        emit JobCreated(jobId, msg.sender);
        return jobId;
    }

    function executeJob(uint256 jobId) external nonReentrant {
        Job storage job = jobs[jobId];
        require(job.state == JobState.Pending, "Job not pending");
        require(msg.sender == job.requester || msg.sender == owner(), "Unauthorized");

        job.state = JobState.Processing;
        ProcessorEntry storage proc = processors[job.processorIndex];

        bytes memory callData = abi.encodeWithSelector(
            proc.selector,
            job.inputData,
            jobId
        );

        (bool success, bytes memory result) = proc.implementation.call{gas: proc.gasLimit}(callData);

        if (success && result.length > 0) {
            job.outputData = result;
            job.state = JobState.Complete;
            _dispatchCallback(job, jobId);
            emit JobCompleted(jobId);
        } else {
            job.state = JobState.Failed;
        }
    }

    function _dispatchCallback(Job storage job, uint256 jobId) internal {
        if (job.callbackTarget != address(0)) {
            require(approvedCallbackTargets[job.callbackTarget], "Callback not approved");
            bytes memory cbData = abi.encodeWithSelector(
                job.callbackSelector,
                jobId,
                job.outputData
            );
            (bool cbSuccess,) = job.callbackTarget.call{gas: CALLBACK_GAS_LIMIT}(cbData);
            // Non-critical: don't revert on callback failure
            if (!cbSuccess) {
                emit CallbackFailed(jobId, job.callbackTarget);
            }
        }
    }

    event CallbackFailed(uint256 indexed jobId, address target);

    function chainProcessors(
        uint256[] calldata processorIds,
        bytes calldata initialInput,
        address finalCallback,
        bytes4 finalSelector
    ) external nonReentrant returns (uint256[] memory) {
        require(processorIds.length > 0 && processorIds.length <= 8, "Invalid chain length");
        require(
            finalCallback == address(0) || approvedCallbackTargets[finalCallback],
            "Callback target not approved"
        );

        uint256[] memory jobIds = new uint256[](processorIds.length);
        bytes memory currentData = initialInput;

        for (uint256 i = 0; i < processorIds.length; i++) {
            ProcessorEntry storage proc = processors[processorIds[i]];
            require(proc.active, "Processor inactive in chain");

            // Build dynamic call using processor's registered selector
            bytes memory callData = abi.encodeWithSelector(
                proc.selector,
                currentData,
                jobCount + i
            );

            (bool success, bytes memory result) = proc.implementation.call{gas: proc.gasLimit}(callData);
            require(success, "Chain step failed");

            // Decode the result - here we use the raw return as next input
            currentData = abi.decode(result, (bytes));

            jobIds[i] = jobCount++;
            jobs[jobIds[i]] = Job({
                requester: msg.sender,
                processorIndex: processorIds[i],
                inputData: i == 0 ? initialInput : currentData,
                outputData: currentData,
                state: JobState.Complete,
                callbackTarget: i == processorIds.length - 1 ? finalCallback : address(0),
                callbackSelector: i == processorIds.length - 1 ? finalSelector : bytes4(0)
            });
        }

        // Dispatch final callback with accumulated result
        if (finalCallback != address(0)) {
            Job storage finalJob = jobs[jobIds[processorIds.length - 1]];
            _dispatchCallback(finalJob, jobIds[processorIds.length - 1]);
        }

        return jobIds;
    }

    function deactivateProcessor(uint256 processorId) external onlyOwner {
        processors[processorId].active = false;
        approvedProcessors[processors[processorId].implementation] = false;
    }

    function getJobResult(uint256 jobId) external view returns (bytes memory) {
        require(jobs[jobId].state == JobState.Complete, "Job not complete");
        require(msg.sender == jobs[jobId].requester || msg.sender == owner(), "Unauthorized");
        return jobs[jobId].outputData;
    }
}
